package com.example.starter.spectrum;

import org.springframework.http.HttpStatus;

/**
 * 业务 API 异常，携带 HTTP 状态码、机器可读错误码与可选明细。
 */
public class ApiException extends RuntimeException {

    private final HttpStatus status;
    private final String code;
    private final transient Object details;

    public ApiException(HttpStatus status, String code, String message) {
        this(status, code, message, null);
    }

    public ApiException(HttpStatus status, String code, String message, Object details) {
        super(message);
        this.status = status;
        this.code = code;
        this.details = details;
    }

    public static ApiException badRequest(String code, String message) {
        return new ApiException(HttpStatus.BAD_REQUEST, code, message);
    }

    public static ApiException notFound(String message) {
        return new ApiException(HttpStatus.NOT_FOUND, "NOT_FOUND", message);
    }

    public static ApiException conflict(String code, String message) {
        return new ApiException(HttpStatus.CONFLICT, code, message);
    }

    public static ApiException unprocessable(String code, String message, Object details) {
        return new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, code, message, details);
    }

    public HttpStatus getStatus() {
        return status;
    }

    public String getCode() {
        return code;
    }

    public Object getDetails() {
        return details;
    }
}

package com.example.starter.spectrum.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.util.List;

/**
 * 建网请求：一次定义 1~20 个唯一台站及有向干扰边；网络配置创建后不可修改。
 */
public record CreateNetworkRequest(
        @NotBlank(message = "networkId 不能为空")
        @Size(max = 64, message = "networkId 长度不能超过64")
        String networkId,
        @Size(max = 128, message = "name 长度不能超过128")
        String name,
        @NotEmpty(message = "stations 至少包含1个台站")
        @Valid
        List<StationInput> stations,
        @Valid
        List<EdgeInput> edges
) {
    /**
     * 台站定义：干扰预算为 0~1000 的整数。
     */
    public record StationInput(
            @NotBlank(message = "stationId 不能为空")
            @Size(max = 64, message = "stationId 长度不能超过64")
            String stationId,
            @NotNull(message = "interferenceBudget 不能为空")
            @Min(value = 0, message = "interferenceBudget 范围为0~1000")
            @Max(value = 1000, message = "interferenceBudget 范围为0~1000")
            Integer interferenceBudget
    ) {
    }

    /**
     * 有向干扰边定义：from->to 同频干扰量 0~1000；禁止自环与重复边。
     */
    public record EdgeInput(
            @NotBlank(message = "fromStationId 不能为空")
            String fromStationId,
            @NotBlank(message = "toStationId 不能为空")
            String toStationId,
            @NotNull(message = "interference 不能为空")
            @Min(value = 0, message = "interference 范围为0~1000")
            @Max(value = 1000, message = "interference 范围为0~1000")
            Integer interference
    ) {
    }
}

package com.example.starter.spectrum.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;

import java.util.List;

/**
 * 频率方案提交：1~20 个不重复台站的新频道（或静默值0），携带 expectedVersion 与全局唯一 planKey。
 */
public record PlanSubmitRequest(
        @NotNull(message = "expectedVersion 不能为空")
        @Min(value = 1, message = "expectedVersion 必须为正整数")
        Integer expectedVersion,
        @NotBlank(message = "planKey 不能为空")
        String planKey,
        @NotEmpty(message = "assignments 至少包含1个台站")
        @Valid
        List<AssignmentInput> assignments
) {
    /**
     * 单台站频道指派：channel=0 表示静默，1~8 为频道号；未列台站保持原状态。
     */
    public record AssignmentInput(
            @NotBlank(message = "stationId 不能为空")
            String stationId,
            @NotNull(message = "channel 不能为空")
            @Min(value = 0, message = "channel 范围为0~8，0表示静默")
            @Max(value = 8, message = "channel 范围为0~8，0表示静默")
            Integer channel
    ) {
    }
}

package com.example.starter.spectrum.dto;

import java.util.List;

/**
 * 网络当前状态视图：台站按建网定义顺序输出，channel=0 表示静默。
 */
public record NetworkStateView(
        String networkId,
        String name,
        int version,
        List<StationView> stations,
        List<EdgeView> edges
) {
    public record StationView(
            String stationId,
            int position,
            int interferenceBudget,
            int channel
    ) {
    }

    public record EdgeView(
            String fromStationId,
            String toStationId,
            int interference
    ) {
    }
}

package com.example.starter.spectrum.dto;

import java.time.OffsetDateTime;
import java.util.List;

/**
 * 方案提交结果 / 不可变历史记录视图。
 */
public record PlanResultView(
        String planKey,
        String requestId,
        int versionFrom,
        int versionTo,
        NetworkStateView before,
        NetworkStateView after,
        List<StationInterference> interferenceSummary,
        OffsetDateTime createdAt
) {
    /**
     * 单个接收台站的累计干扰裁决明细：静默台站 totalInterference 恒为0且不参与预算校验。
     */
    public record StationInterference(
            String stationId,
            int channel,
            int totalInterference,
            int interferenceBudget,
            boolean withinBudget
    ) {
    }
}

