                        + "FROM spectrum_plan WHERE request_id = ?",
                rs -> rs.next() ? Optional.of(PLAN_MAPPER.mapRow(rs, 1)) : Optional.empty(),
                requestId);
    }

    public Optional<IdempotentRecord> findRequest(String requestId) {
        return jdbcTemplate.query(
