            {
              "networkId": "%s",
              "stations": [
                {"stationId": "x", "interferenceBudget": 1000},
                {"stationId": "y", "interferenceBudget": 1000},
                {"stationId": "r", "interferenceBudget": 100}
              ],
              "edges": [
                {"fromStationId": "x", "toStationId": "r", "interference": 60},
                {"fromStationId": "y", "toStationId": "r", "interference": 60}
              ]
            }
            """.formatted(id);
